#! /bin/bash
# Generate charts/data-space-connector/values.schema.json from the chart's values.yaml, or, with
# --check, fail when the committed schema is not what values.yaml generates.
#
# The schema is generated by helm-schema (https://github.com/dadav/helm-schema): types come from
# the defaults, descriptions from the `# --` comments, and every object only accepts the keys its
# default declares. `# @schema` blocks in values.yaml adjust that where the default cannot tell,
# see CLAUDE.md. The subcharts are left out (-n): their keys are left open in values.yaml and
# validated by each subchart's own schema.
#
# helm-schema has no container image, so the release archive is downloaded once into the user's
# cache and checked against the checksum pinned below, the same way the other scripts pin their
# images.

set -euo pipefail

VERSION="0.23.5"
CHART="charts/data-space-connector"

arch="$(uname -m)"
[ "$arch" = "aarch64" ] && arch="arm64"
platform="$(uname -s)_${arch}"
# sha256 of the release archives, from the checksums.txt of the release. A case rather than an
# associative array: the bash macOS ships is 3.2.
case "$platform" in
    Linux_x86_64)  expected="b6e5334de9651a06b5fc7af573a114fda5177ee13d4c3dc59e3b6f21d0695552" ;;
    Linux_arm64)   expected="9685fb7b11de591aebe0bcd62b84edbeb6ae190876078ca42cbed7116acd9f21" ;;
    Darwin_x86_64) expected="6f5049c58d3f7f10a985242e72c45b62fc45c66e3b02cb9faeca6cc272beec1c" ;;
    Darwin_arm64)  expected="f64911ec568699772272db58bd1aba047c739933b026f1f1a7235141862ed54e" ;;
    *)
        echo "helm-schema ${VERSION} is not pinned for ${platform}" >&2
        exit 1
        ;;
esac

bin_dir="${XDG_CACHE_HOME:-$HOME/.cache}/helm-schema/${VERSION}"
bin="${bin_dir}/helm-schema"
if [ ! -x "$bin" ]; then
    mkdir -p "$bin_dir"
    archive="${bin_dir}/helm-schema.tar.gz"
    curl -fsSL -o "$archive" \
        "https://github.com/dadav/helm-schema/releases/download/${VERSION}/helm-schema_${VERSION}_${platform}.tar.gz"
    if command -v sha256sum >/dev/null; then
        actual="$(sha256sum "$archive" | cut -d' ' -f1)"
    else
        actual="$(shasum -a 256 "$archive" | cut -d' ' -f1)"
    fi
    if [ "$actual" != "$expected" ]; then
        rm -f "$archive"
        echo "checksum mismatch for helm-schema ${VERSION} (${platform})" >&2
        exit 1
    fi
    tar -xzf "$archive" -C "$bin_dir" helm-schema
    rm -f "$archive"
fi

# Generated in a copy holding only Chart.yaml and values.yaml: with the subcharts downloaded into
# charts/, helm-schema unpacks them and walks the charts nested inside, even with --no-dependencies.
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
mkdir -p "${work}/chart"
cp "${CHART}/Chart.yaml" "${CHART}/values.yaml" "${work}/chart/"
"$bin" --chart-search-root "${work}/chart" --no-dependencies --skip-auto-generation required \
    --append-newline --log-level warning

if [ "${1:-}" = "--check" ]; then
    if ! cmp -s "${work}/chart/values.schema.json" "${CHART}/values.schema.json"; then
        echo "${CHART}/values.schema.json is not what values.yaml generates: run .github/scripts/values-schema.sh" >&2
        exit 1
    fi
else
    cp "${work}/chart/values.schema.json" "${CHART}/values.schema.json"
fi
